/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    const n = parseInt(lines[0]);
    const nums = lines[1].split(" ").map(Number);

    console.log(getResult(nums, n));

    lines.length = 0;
  }
});

function getResult(nums, n) {
  let leftSum = 0;
  let rightSUm = nums.reduce((a, b) => a + b);

  let maxDiff = 0;
  for (let i = 0; i < n-1; i++) {
    leftSum += nums[i];
    rightSUm -= nums[i];

    const diff = Math.abs(leftSum - rightSUm);
    if (diff > maxDiff) maxDiff = diff;
  }

  return maxDiff;
}

Java:
import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = Integer.parseInt(sc.nextLine());
    long[] nums = Arrays.stream(sc.nextLine().split(" ")).mapToLong(Long::parseLong).toArray();

    System.out.println(getResult(nums, n));
  }

  public static long getResult(long[] nums, int n) {
    long leftSum = 0;
    long rightSum = Arrays.stream(nums).sum();

    long maxDiff = 0;

    for (int i = 0; i < n - 1; i++) {
      leftSum += nums[i];
      rightSum -= nums[i];

      long diff = Math.abs(leftSum - rightSum);
      if (diff > maxDiff) maxDiff = diff;
    }

    return maxDiff;
  }
}

