#include <stdio.h>

#define MAX_SIZE 100000
#define MAX(a,b) a > b ? a : b
#define DIFF_ABS(a, b) a > b ? a - b : b - a

long getResult(long* nums, int n);
long sum(long* arr, int arr_size);

