long getResult(long* nums, int n)
{
	long leftSum = 0;
	long rightSum = sum(nums, n);

	long maxDiff = 0;

	for(int i=0; i<n-1; i++) {
		leftSum += nums[i];
		rightSum -= nums[i];

		long diff = DIFF_ABS(leftSum, rightSum);
		maxDiff = MAX(maxDiff, diff);
	}

	return maxDiff;
}

